"""Helper for driving the authors' train_FEGNN.py as a subprocess and parsing its log.

Importable, no side effects on import.
"""
import math
import os
import re
import subprocess
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
REPO = os.path.join(HERE, "repo")
LOGS = os.path.join(HERE, "logs")

BEST_RE = re.compile(
    r"Best epoch\s+(\d+)\s+for run\s+(\d+):\s*"
    r"train loss:\s*(-?[0-9.eE+]+),\s*val loss:\s*(-?[0-9.eE+]+),\s*"
    r"val acc:\s*(-?[0-9.eE+]+),\s*test acc\s+(-?[0-9.eE+]+)"
)
AVG_RE = re.compile(r"Average Test acc for ([a-zA-Z_]+):\s*(-?[0-9.eE+]+),\s*Val acc:\s*(-?[0-9.eE+]+)")


def log_path(dataset, seed, log_dir=LOGS):
    return os.path.join(log_dir, f"{dataset}_seed{seed}.log")


def command(dataset, seed, runs, epochs=None):
    cmd = [sys.executable, "train_FEGNN.py", "--dataset", dataset, "--no-cuda",
           "--runs", str(runs), "--seed", str(seed)]
    if epochs:
        cmd += ["--epochs", str(epochs)]
    return cmd


def launch(dataset, seed, runs, epochs=None, threads=2, log_dir=LOGS):
    """Start one seed job; returns (Popen, logfile)."""
    os.makedirs(log_dir, exist_ok=True)
    path = log_path(dataset, seed, log_dir)
    env = dict(os.environ)
    env["OMP_NUM_THREADS"] = str(threads)
    env["MKL_NUM_THREADS"] = str(threads)
    env["PYTHONIOENCODING"] = "utf-8"
    fh = open(path, "w", encoding="utf-8")
    fh.write("$ " + " ".join(command(dataset, seed, runs, epochs)) + f"   (cwd={REPO}, "
             f"OMP_NUM_THREADS={threads})\n")
    fh.flush()
    p = subprocess.Popen(command(dataset, seed, runs, epochs), cwd=REPO, stdout=fh,
                         stderr=subprocess.STDOUT, env=env)
    p._log_fh = fh
    return p, path


def parse_log(path):
    """Return dict with per-run test acc / val acc / best epoch and the script's own average."""
    if not os.path.exists(path):
        return {"runs": [], "script_avg": None, "error": "missing log"}
    with open(path, encoding="utf-8", errors="replace") as f:
        text = f.read()
    runs = []
    for m in BEST_RE.finditer(text):
        epoch, idx, tl, vl, va, ta = m.groups()
        try:
            runs.append({"run": int(idx), "best_epoch": int(epoch),
                         "train_loss": float(tl), "val_loss": float(vl),
                         "val_acc": float(va), "test_acc": float(ta)})
        except ValueError:
            continue
    avg = None
    for m in AVG_RE.finditer(text):
        avg = {"dataset": m.group(1), "test_acc": float(m.group(2)), "val_acc": float(m.group(3))}
    return {"runs": runs, "script_avg": avg, "error": None}


def mean(xs):
    return sum(xs) / len(xs) if xs else float("nan")


def std(xs):
    if len(xs) < 2:
        return 0.0
    mu = mean(xs)
    return math.sqrt(sum((x - mu) ** 2 for x in xs) / (len(xs) - 1))


def ci95_normal(xs):
    """1.96 * std / sqrt(n) - the paper's CI style (R15)."""
    if not xs:
        return float("nan")
    return 1.96 * std(xs) / math.sqrt(len(xs))


def ci95_student(xs):
    """Student-t 95% interval half-width with a plain-stdlib critical-value table."""
    n = len(xs)
    if n < 2:
        return float("nan")
    table = {1: 12.706, 2: 4.303, 3: 3.182, 4: 2.776, 5: 2.571, 6: 2.447, 7: 2.365,
             8: 2.306, 9: 2.262, 10: 2.228, 12: 2.179, 14: 2.145, 16: 2.120,
             18: 2.101, 20: 2.086, 24: 2.064, 30: 2.042, 40: 2.021, 50: 2.009,
             60: 2.000, 80: 1.990, 100: 1.984, 120: 1.980}
    dof = n - 1
    keys = sorted(table)
    t = table[keys[-1]]
    for k in keys:
        if dof <= k:
            t = table[k]
            break
    return t * std(xs) / math.sqrt(n)

"""Helper for driving the authors' train_FEGNN.py as a subprocess and parsing its log.

Importable, no side effects on import.

Log format written by repo/train_FEGNN.py (stdout+stderr merged, tqdm interleaves carriage
returns and ANSI cursor escapes):

    Namespace(no_cuda=True, cuda=2, seed=42, dataset='chameleon', ...)
    Best epoch 51 for run 0: train loss: 0.0573, val loss: 0.7300, val acc: 0.7758, test acc 0.7493
    Average Test acc for chameleon: 0.7332, Val acc: 0.7690
"""
import math
import os
import re
import subprocess
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
REPO = os.path.join(HERE, "repo")
LOGS = os.path.join(HERE, "logs")

ANSI_RE = re.compile(r"\x1b\[[0-9;?]*[A-Za-z]|\x1b[()][B0-9]|\r")

BEST_RE = re.compile(
    r"Best epoch\s+(\d+)\s+for run\s+(\d+):\s*"
    r"train loss:\s*(-?[0-9.eE+]+),\s*val loss:\s*(-?[0-9.eE+]+),\s*"
    r"val acc:\s*(-?[0-9.eE+]+),\s*test acc\s+(-?[0-9.eE+]+)"
)
AVG_RE = re.compile(r"Average Test acc for ([a-zA-Z_0-9]+):\s*(-?[0-9.eE+nan]+),\s*"
                    r"Val acc:\s*(-?[0-9.eE+nan]+)")
NS_RE = re.compile(r"Namespace\((.{20,}?)\)\s*(?:\n|$)")


def clean(text):
    """Drop ANSI escapes and normalise carriage returns so regexes can match across tqdm."""
    text = ANSI_RE.sub("\n", text)
    return text


def log_path(dataset, seed, log_dir=LOGS):
    tag = f"{dataset}_seed{seed}" if seed is not None else dataset
    return os.path.join(log_dir, f"{tag}.log")


def command(dataset, seed, runs, epochs=None):
    cmd = [sys.executable, "train_FEGNN.py", "--dataset", dataset, "--no-cuda",
           "--runs", str(runs)]
    if seed is not None:
        cmd += ["--seed", str(seed)]
    if epochs:
        cmd += ["--epochs", str(epochs)]
    return cmd


def launch(dataset, seed, runs, epochs=None, threads=2, log_dir=LOGS):
    """Start one job of the authors' script. Returns (Popen, logfile)."""
    os.makedirs(log_dir, exist_ok=True)
    path = log_path(dataset, seed, log_dir)
    env = dict(os.environ)
    env["OMP_NUM_THREADS"] = str(threads)
    env["MKL_NUM_THREADS"] = str(threads)
    env["PYTHONIOENCODING"] = "utf-8"
    fh = open(path, "w", encoding="utf-8", errors="replace")
    fh.write("$ " + " ".join(command(dataset, seed, runs, epochs)) +
             f"   (cwd={REPO})\n")
    fh.flush()
    p = subprocess.Popen(command(dataset, seed, runs, epochs), cwd=REPO, stdout=fh,
                         stderr=subprocess.STDOUT, env=env)
    p._log_fh = fh
    return p, path


def _f(x):
    try:
        return float(x)
    except ValueError:
        return float("nan")


def parse_log(path):
    """Return {'runs': [...], 'script_avg': float|None, 'namespace': dict|None, 'error': ...}."""
    if not os.path.exists(path):
        return {"runs": [], "script_avg": None, "namespace": None, "error": "missing log"}
    with open(path, encoding="utf-8", errors="replace") as f:
        raw = f.read()
    text = clean(raw)

    runs = []
    for m in BEST_RE.finditer(text):
        epoch, idx, tl, vl, va, ta = m.groups()
        runs.append({"run": int(idx), "best_epoch": int(epoch), "train_loss": _f(tl),
                     "val_loss": _f(vl), "val_acc": _f(va), "test_acc": _f(ta)})

    avg = None
    for m in AVG_RE.finditer(text):          # last occurrence wins
        avg = {"dataset": m.group(1), "test_acc": _f(m.group(2)), "val_acc": _f(m.group(3))}

    ns = None
    m = NS_RE.search(text)
    if m:
        ns = {}
        for part in m.group(1).split(", "):
            if "=" in part:
                k, v = part.split("=", 1)
                if re.fullmatch(r"[A-Za-z_][A-Za-z_0-9]*", k):
                    ns[k] = v
    return {"runs": runs, "script_avg": avg, "namespace": ns, "error": None}


