    """1.96 * std / sqrt(n) - the paper's CI style (R15)."""
    xs = [x for x in xs if x == x]
    if not xs:
        return float("nan")
    return 1.96 * std(xs) / math.sqrt(len(xs))


_T_TABLE = {1: 12.706, 2: 4.303, 3: 3.182, 4: 2.776, 5: 2.571, 6: 2.447, 7: 2.365,
            8: 2.306, 9: 2.262, 10: 2.228, 12: 2.179, 14: 2.145, 16: 2.120, 18: 2.101,
            20: 2.086, 24: 2.064, 30: 2.042, 40: 2.021, 50: 2.009, 60: 2.000,
            80: 1.990, 100: 1.984, 120: 1.980}


def ci95_student(xs):
    xs = [x for x in xs if x == x]
    n = len(xs)
    if n < 2:
        return float("nan")
    dof = n - 1
    t = _T_TABLE[max(k for k in _T_TABLE if k <= dof)] if dof in _T_TABLE else 1.96
    if dof > 120:
